    public static void Repair(string inputs,string baseline,string output)
    {
        Directory.CreateDirectory(output);foreach(string n in new[]{"resources.db","personal.db"})File.Copy(Path.Combine(inputs,n),Path.Combine(output,n),false);var store=new Store(output);string resource=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(store.Database)));store.ApplyClusterRepairBaseline(baseline);var clusters=store.Clusters();if(clusters.Single(c=>c.Members.Contains("南澳区财政局FG/GJ01")).Members.Length!=3)throw new Exception("full repair finance mismatch");string personal=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(store.Personal)));store.ApplyClusterRepairBaseline(baseline);if(personal!=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(store.Personal)))||resource!=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(store.Database))))throw new Exception("repair repeat changed data or resource database modified");Console.WriteLine($"FULL REPAIR PASS: clusters={clusters.Count}; confirmed={clusters.Count(c=>c.Status=="已确认")}; review={clusters.Count(c=>c.Status=="需核对")}; filtered={store.FilteredClusters.Count}; resource bytes untouched; repeat idempotent");
        Csv.Write(Path.Combine(output,"集群分析结果.csv"),new[]{new object?[]{"集群名称","所属站点","成员数","状态","原因","成员"}}.Concat(clusters.Select(c=>new object?[]{c.Name,c.Station,c.Members.Length,c.Status,c.Reason,string.Join('；',c.Members)})));
    }
    public static Task Full(string inputs,string output)
    {
        Directory.CreateDirectory(output);foreach(string n in new[]{"resources.db","personal.db"})File.Copy(Path.Combine(inputs,n),Path.Combine(output,n),true);var store=new Store(output);
        store.ApplyStationFiles(new[]{"光分纤箱-1.CSV","光交接箱-1.CSV"}.Select(n=>(Path.Combine(inputs,n),"",(string?)null)));
        store.SaveClusterImport(Path.Combine(inputs,"集群管理.xlsx"));var clusters=store.Clusters();var finance=clusters.Single(x=>x.Members.Contains("南澳区财政局FG/GJ01"));if(finance.Members.Length!=3)throw new Exception("财政局应为三成员");
        Console.WriteLine($"FULL clusters={clusters.Count} confirmed={clusters.Count(x=>x.Status=="已确认")} review={clusters.Count(x=>x.Status=="需核对")} routing={clusters.Count(x=>x.Enabled)} filtered={store.FilteredClusters.Count}; finance members={finance.Members.Length}; station={finance.Station}");
        foreach(var x in clusters.Where(x=>x.Name.Contains("莲下环")||x.Name.Contains("豪宇天下")))Console.WriteLine(JsonSerializer.Serialize(x));
        if(clusters.Any(x=>x.Members.Contains("现场已合并）")))throw new Exception("括号备注仍被拆分");
        var graph=store.Graph;var a=graph.Nodes.First(x=>x.Name=="汕头南澳南澳综合楼汇聚点四楼机房传输1/AF01B/ODF20");var b=graph.Nodes.First(x=>x.Name=="汕头南澳后宅汇聚点一楼机房传输1/ODF01");var options=new RouteOptions(a.Id,b.Id,10,8,8,RouteOrder.Capacity,[],[]);var routes=Routing.Find(graph,options);var route=routes.Routes.First(x=>x.Edges.Length==1);var plan=ExportPlan.FromRoute(graph,route,options,1);if(plan.Sequence.Length!=2||plan.Jumps!=0||plan.Transfers.Length!=0)throw new Exception("单段路由回归失败");RouteWorkbook.Write(Path.Combine(output,"单中继段修正验证.xlsx"),[plan]);Console.WriteLine($"FULL route: {string.Join(" → ",plan.Sequence)}; {plan.Length}m; jumps={plan.Jumps}");
        var pos=graph.Nodes.Where(x=>x.Name.Contains("POS",StringComparison.OrdinalIgnoreCase)).ToArray();if(pos.Any(x=>x.Type!="分纤箱")||graph.Nodes.Any(x=>x.Type.Split(';').Contains("站点")))throw new Exception("POS/站点分类失败");Console.WriteLine($"FULL POS={pos.Length}, all classified 分纤箱; station category absent");
        // Compact, private migration payload: only source evidence and original cluster rows, no personal settings or database resources.
        string baseline=Path.Combine(output,"集群站点修复基线.db");using(var c=new SqliteConnection($"Data Source={baseline}")){c.Open();using var q=c.CreateCommand();q.CommandText="ATTACH DATABASE $p AS src";q.Parameters.AddWithValue("$p",store.Personal);q.ExecuteNonQuery();foreach(string t in new[]{"facility_stations","station_sources","cluster_inputs"}){q.CommandText=$"CREATE TABLE {t} AS SELECT * FROM src.{t}";q.ExecuteNonQuery();}q.CommandText="VACUUM";q.ExecuteNonQuery();}
        string package=Path.Combine(output,"resources-r143-validation.zip");store.BuildDataPackage(package,"2026-10-28.143");string work=Path.Combine(output,"private-test-workspace");Publishing.Initialize(work,"https://updates.example.test/");var release=Publishing.Release(work,"data","2026-10-28.143",package);Console.WriteLine($"FULL package bytes={new FileInfo(package).Length}; parts={release.Resources!.Parts?.Length??1}; active_files={PublishingDelivery.ActiveFiles(work).Length}");return Task.CompletedTask;
    }
    public static async Task Run(string root,Action<bool,string> check)
    {
        check(Store.SplitClusterMembers("莲下环PX01/GJ01-1（废弃，现场已合并）,莲下环PX01/GJ01-1").Length==2,"R143 balanced parentheses preserve commas in complete cluster names");
        check(Store.ClassifyType("FGL003-POS003-1:8","站点")=="分纤箱"&&Store.ClassifyType("普通设施","站点")=="未识别"&&Store.ClassifyType("普通设施","")=="未识别","R143 POS override and supported categories apply to old and newly imported types");
        string raw=Path.Combine(root,"raw-facilities.csv");File.WriteAllText(raw,"ID,设施名称,设施编码,所属末端网格,所属地市,所属区县,站点名称/位置点,机房名称,所属社区\n441000000000010359063936,\"原始设施名,\"编码,网格,汕头,南澳县,站甲,,社区\n");
        check(Csv.IsRawFacility(raw,"UTF-8")&&Csv.ReadRawFacility(raw,"UTF-8").Last()[1]=="\"原始设施名","R143 fixed facility export preserves literal unmatched quotes without shifting station fields");
        string folder=Path.Combine(root,"r143");Directory.CreateDirectory(folder);string csv=Path.Combine(folder,"resources.csv");Csv.Write(csv,new object?[][]{["ID","始端设施","终端设施","长度","空闲数量","中继纤芯数量"],["a","GJ01","GF01",1,2,4]});var s=new Store(Path.Combine(folder,"data"));await s.ImportAsync(csv,"自动",Store.Fields.ToDictionary(f=>f,f=>f),1,null,default);
        string types=Path.Combine(folder,"设施.csv");Csv.Write(types,new object?[][]{["设施名称","站点名称/位置点"],["GJ01","站甲"],["GF01","站甲"],["GF02","站甲"],["GJ99",""]});s.ApplyStationFiles([(types,"",null)]);
        string table=Path.Combine(folder,"clusters.csv");Csv.Write(table,new object?[][]{["设备名称","集群类型","集群列表","所属站点"],["GJ01","光交接箱","GJ01",""],["GJ99","光交接箱","GJ99",""]});s.SaveClusterImport(table);var cluster=s.Clusters().Single();check(cluster.Members.Length==3&&cluster.Station=="站甲"&&cluster.Enabled&&cluster.Status=="已确认"&&cluster.Reason.Contains("暂无中继段"),"R143 station expands singleton across cabinet and splitters; source-only member does not invalidate the whole group");check(s.FilteredClusters.Count==1&&File.Exists(Path.Combine(s.Root,"集群过滤报告.csv")),"R143 unresolved singleton is excluded with an audit reason");
        Csv.Write(types,new object?[][]{["设施名称","站点名称/位置点"],["GJ01","站甲"],["GF01","站甲"],["GF02","站乙"],["GJ99",""]});s.ApplyStationFiles([(types,"",null)]);check(s.Clusters().Single().Members.Length==2,"R143 reimport replaces station evidence and recalculates memberships without stale expanded members");
        var g=new Graph([new(0,"selected-start","机房",true),new(1,"ODF12","机房",true),new(2,"ODF06","机房",true),new(3,"selected-end","机房",true)],[new(0,"a","",1,2,2391.53,136,136,"")],"test");var route=new Route([0,3],[0],2391.53,0,0,136){Steps=[new(0,1,2)],Transfers=[new(0,1,0),new(2,3,1)]};var plan=ExportPlan.FromRoute(g,route,new(0,3,10,8,8,RouteOrder.Distance,[],[]),1);check(plan.Sequence.SequenceEqual(new[]{"ODF12","ODF06"})&&plan.Transfers.Length==0&&plan.Jumps==0,"R143 one real segment has only two route endpoints and no fabricated endpoint jump entries");
        // Use incompressible data to cross the real Pages limit, then exercise the complete signed publication and download path.
        string zip=Path.Combine(folder,"large.zip");using(var z=ZipFile.Open(zip,ZipArchiveMode.Create)){using(var w=new StreamWriter(z.CreateEntry("manifest.json").Open()))w.Write("{\"Version\":\"test143\"}");using var stream=z.CreateEntry("noise",CompressionLevel.NoCompression).Open();for(int i=0;i<26;i++)stream.Write(RandomNumberGenerator.GetBytes(1024*1024));}
        string work=Path.Combine(folder,"work");Publishing.Initialize(work,"https://updates.example.test/");var release=Publishing.Release(work,"data","test143",zip);var item=release.Resources!;check(item.Parts?.Length==2&&item.Parts.All(p=>p.Bytes<25L*1024*1024)&&item.MinimumProgram=="1.4.3"&&!File.Exists(Path.Combine(work,"site","data","test143","resources-test143.zip")),"R143 publisher emits automatic 24MiB parts with signed per-part and overall metadata, no oversized public ZIP");string[] active=PublishingDelivery.ActiveFiles(work);check(active.Any(p=>p.EndsWith(".zip.002"))&&active[^1]=="manifest.json"&&!active.Any(p=>p.Contains("private")),"R143 publishing validates part files and keeps manifest last");var config=Updates.LoadConfig(Path.Combine(work,"update-service.json"))!;
        using var http=new HttpClient(new Files(Path.Combine(work,"site")));string download=await Updates.Download(config,item,folder,default,transport:http);check(SHA256.HashData(File.ReadAllBytes(download)).SequenceEqual(SHA256.HashData(File.ReadAllBytes(zip))),"R143 client downloads parts in order and reconstructs exact original ZIP");File.Delete(download);
        async Task Reject(ReleaseItem broken,string label,HttpClient client){bool failed=false;try{await Updates.Download(config,broken,folder,default,transport:client);}catch(Exception ex)when(ex is InvalidDataException or HttpRequestException){failed=true;}check(failed&&!Directory.GetFiles(folder,"*.download").Any(),label);}
        using var corrupt=new HttpClient(new Files(Path.Combine(work,"site"),corrupt:true));await Reject(item,"R143 corrupt or missing part cannot leave an installable partial file",corrupt);await Reject(item with{Sha256=new string('0',64)},"R143 combined hash is independently checked after individual parts pass",http);await Reject(item with{Parts=[item.Parts![0],item.Parts[1] with{Url="https://other.example.test/b.zip.002"}]},"R143 cross-origin part URL is rejected before network access",http);
        using var cts=new CancellationTokenSource();cts.Cancel();bool cancelled=false;try{await Updates.Download(config,item,folder,cts.Token,transport:http);}catch(OperationCanceledException){cancelled=true;}check(cancelled&&!Directory.GetFiles(folder,"*.download").Any(),"R143 cancellation cleans partial downloads");
        Publishing.SaveConfiguration(work,"https://moved.example.test/");var moved=Updates.VerifyEnvelope(File.ReadAllBytes(Path.Combine(work,"site","manifest.json")),config.PublicKeyPem);check(moved.Resources!.Parts!.All(p=>p.Url.StartsWith("https://moved.example.test/"))&&PublishingDelivery.ActiveFiles(work).Length==active.Length,"R143 service URL changes rebase every signed part without changing key or files");
        string repair=Path.Combine(folder,"repair.db");using(var c=new SqliteConnection($"Data Source={repair}")){c.Open();using var q=c.CreateCommand();q.CommandText="ATTACH DATABASE $p AS src";q.Parameters.AddWithValue("$p",s.Personal);q.ExecuteNonQuery();foreach(string t in new[]{"facility_stations","station_sources","cluster_inputs"}){q.CommandText=$"CREATE TABLE {t} AS SELECT * FROM src.{t}";q.ExecuteNonQuery();}}
        var legacy=new Store(Path.Combine(folder,"legacy"));await legacy.ImportAsync(csv,"自动",Store.Fields.ToDictionary(f=>f,f=>f),1,null,default);legacy.SaveClusters([new("manual","人工关系","光交箱",["GJ01","GF01"],"人工修改","已确认","",false)]);legacy.ApplyClusterRepairBaseline(repair);legacy.ApplyClusterRepairBaseline(repair);check(legacy.Clusters().Count==1&&legacy.Clusters()[0].Source=="人工修改"&&!legacy.Clusters()[0].Enabled,"R143 repair baseline is idempotent and preserves an existing manually suspended cluster");
        string package=Path.Combine(folder,"catalog.zip");s.BuildDataPackage(package,"data143");var target=new Store(Path.Combine(folder,"client"));using(var prepared=target.PrepareDataPackage(package)){target.ApplyDataPackage(prepared);}check(target.Clusters().Single().Station=="站甲"&&target.Clusters().Single().Members.Length==2,"R143 online data package synchronizes station evidence and original cluster inputs");
    }
    sealed class Files(string site,bool corrupt=false):HttpMessageHandler
    {
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken ct){ct.ThrowIfCancellationRequested();string path=Path.Combine(site,Uri.UnescapeDataString(r.RequestUri!.AbsolutePath.TrimStart('/')));if(!File.Exists(path))return Task.FromResult(new HttpResponseMessage(HttpStatusCode.NotFound));byte[] bytes=File.ReadAllBytes(path);if(corrupt&&bytes.Length>0)bytes[0]^=1;return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(bytes)});}
    }
}
